<script setup lang="ts">
import { computed, ref } from 'vue';
import type { EvidenceBundle, WorkspaceDetails } from '../../../packages/contracts/src/index';
import DiffViewer from './DiffViewer.vue';
const props = defineProps<{ bundle: EvidenceBundle; status: string; details: WorkspaceDetails | null; busy: boolean }>();
const emit = defineEmits<{ decide: [action: 'accept' | 'request_changes' | 'reject', feedback: string] }>();
const feedback = ref('');
const evidence = computed(() => JSON.parse(props.bundle.body_json));
const current = computed(() => props.details && !props.details.dirty && props.details.currentHead === props.bundle.commit_sha && props.details.workspaceDigest === evidence.value.workspaceDigest);
const summaries = computed(() => evidence.value.implementations.map((run: { id: string; stage: string; summary: string }) => ({ ...run, result: JSON.parse(run.summary || '{}') })));
</script>
<template>
  <section class="final-review-panel">
    <div class="section-title"><UIcon name="i-lucide-shield-check" /><h3>{{ status === 'ACCEPTED' ? 'Accepted change' : status === 'REJECTED' ? 'Rejected change' : 'Final human review' }}</h3><UBadge color="neutral" variant="subtle" size="xs">Exact commit</UBadge></div>
    <p>Review the change and its captured evidence. Acceptance records the exact commit and evidence bundle below.</p>
    <UCollapsible class="evidence-disclosure"><UButton color="neutral" variant="ghost" trailing-icon="i-lucide-chevron-down" class="disclosure-trigger"><span>Commit &amp; evidence</span><code>{{ bundle.commit_sha.slice(0, 10) }}</code></UButton><template #content><dl class="artifact-facts px-4"><dt>Commit</dt><dd><code>{{ bundle.commit_sha }}</code></dd><dt>Base</dt><dd><code>{{ evidence.baseSha }}</code></dd><dt>Evidence</dt><dd><code>{{ bundle.sha256_digest }}</code></dd></dl></template></UCollapsible>
    <div v-for="run in summaries" :key="run.id" class="issue-section"><h3>{{ run.stage === 'repair' ? 'Repair summary' : 'Implementation summary' }}</h3><p class="review-summary">{{ run.result.summary }}</p><h3>Known limitations</h3><ul v-if="run.result.limitations?.length" class="limitations-list"><li v-for="limitation in run.result.limitations" :key="limitation">{{ limitation }}</li></ul><p v-else class="field-note">None reported by this attempt.</p></div>
    <div class="section-title"><h3>Required checks</h3><UBadge color="success" variant="subtle" size="xs">{{ evidence.checks.length }} passed</UBadge></div><article v-for="check in evidence.checks" :key="check.id" class="check-card"><div class="check-card-heading"><UIcon name="i-lucide-circle-check" class="tone-success" /><strong>{{ check.name }}</strong><small class="check-commit">exit {{ check.exitCode }}</small></div><code class="check-command">{{ check.commitSha }}</code><UCollapsible class="evidence-disclosure"><UButton color="neutral" variant="ghost" trailing-icon="i-lucide-chevron-down" class="disclosure-trigger">Captured log</UButton><template #content><pre class="log-view">{{ check.log || 'No output captured.' }}</pre></template></UCollapsible></article>
    <div class="evidence-block mt-6"><div class="evidence-block-header"><UIcon name="i-lucide-scan-eye" /><h3>Independent review</h3><UBadge color="success" variant="subtle" size="xs">{{ evidence.review.verdict }}</UBadge></div><div class="evidence-block-body"><p class="review-summary">{{ evidence.review.summary }}</p><p v-if="!evidence.review.findings.length">No outstanding findings reported.</p><ul v-else class="finding-list"><li v-for="(finding, index) in evidence.review.findings" :key="index"><strong>{{ finding.severity }} · {{ finding.title }}</strong><code>{{ finding.file }}</code><p>{{ finding.rationale }}</p><p>{{ finding.suggestedFix }}</p></li></ul></div></div>
    <UCollapsible v-if="evidence.reviewHistory.length > 1" class="evidence-disclosure"><UButton color="neutral" variant="ghost" trailing-icon="i-lucide-chevron-down" class="disclosure-trigger">Earlier review outcomes · {{ evidence.reviewHistory.length - 1 }}</UButton><template #content><article v-for="review in evidence.reviewHistory.slice(0,-1)" :key="review.id" class="history-item"><strong>{{ review.verdict }}</strong><p>{{ review.summary }}</p><code>{{ review.commit_sha }}</code><pre>{{ JSON.stringify(JSON.parse(review.findings_json), null, 2) }}</pre><p class="field-note">Superseded after repair, revalidation, and the passing review above.</p></article></template></UCollapsible>
    <UCollapsible class="evidence-disclosure"><UButton color="neutral" variant="ghost" trailing-icon="i-lucide-chevron-down" class="disclosure-trigger">Reviewed diff · {{ evidence.changedFiles.length }} files</UButton><template #content><div class="file-list"><span v-for="file in evidence.changedFiles" :key="file"><UIcon name="i-lucide-file-code" />{{ file }}</span></div><DiffViewer :diff="evidence.diff" /></template></UCollapsible>
    <div v-if="status === 'FINAL_REVIEW'" class="final-decision"><h3>Your decision</h3><p>Accept the reviewed commit or send focused feedback for another bounded repair.</p><UAlert v-if="!current" color="warning" variant="subtle" description="Refresh the worktree inspection before deciding. Evidence must match the current clean commit." class="mb-4" /><UFormField label="Decision feedback" description="Required for changes or rejection. Changes must stay within the approved scope."><UTextarea v-model="feedback" :rows="3" class="w-full" placeholder="Add your feedback…" /></UFormField><div class="action-row"><UButton size="sm" icon="i-lucide-check" :disabled="busy || !current" @click="emit('decide','accept',feedback)">Accept reviewed commit</UButton><UButton size="sm" color="neutral" variant="outline" :disabled="busy || !current || !feedback.trim()" @click="emit('decide','request_changes',feedback)">Request changes</UButton><UButton size="sm" color="error" variant="ghost" :disabled="busy || !current || !feedback.trim()" @click="emit('decide','reject',feedback)">Reject</UButton></div></div>
  </section>
</template>
